  const updateItemEnviada = async (
    itemId: number,
    enviada: string,
    batches?: Record<string, number>,
  ) => {
    // Determine the 'lote' string from batches if provided
    let loteString = '';
    if (batches) {
      loteString = Object.entries(batches)
        .filter(([_, qty]) => qty > 0)
        .map(([id, qty]) => `${id}:${qty}`)
        .join(';');
    }

    setItens((prev) =>
      prev.map((i) =>
        i.id === itemId
          ? {
              ...i,
              quantidade_enviada: enviada,
              coletado: String(enviada).trim() !== '',
              selectedBatches: batches || i.selectedBatches,
              lote: loteString || i.lote,
            }
          : i,
      ),
    );

    setPendingSent((prev) => ({ ...prev, [itemId]: enviada }));

    // Update DB
    const updatePayload: any = { quantidade_enviada: enviada };
    if (batches) {
      updatePayload.lote = loteString;
    }

    await supabase
      .from('requisicoes_itens' as any)
      .update(updatePayload)
      .eq('id', itemId);

    if (user) {
      const alvo = itens.find((i) => i.id === itemId);
      const nomeUser = myProfileName;
      const nomeProd = alvo?.produto_nome || 'Item';
      const color = colorForUser(user.id);
      channelRef.current?.send({
        type: 'broadcast',
        event: 'user_event',
        payload: {
          text: `${nomeUser} definiu quantidade enviada de ${nomeProd}: ${enviada}`,
          color,
        },
      });
      pushLog(
        `${nomeUser} definiu quantidade enviada de ${nomeProd}: ${enviada}`,
        color,
