      logExpeditionEvent(null, {
        title: 'Quantidade Ajustada',
        description: `${nomeUser} definiu quantidade de "${nomeProd}" para ${enviada}`,
        type: 'item_action',
        user_name: nomeUser,
        requisitionId: Number(requisicaoId),
        metadata: {
          item_id: itemId,
          item_name: nomeProd,
          quantity: enviada,
          action: 'update_quantity',
        },
      });
