  const handleBatchChange = (
    itemId: number,
    batchId: string,
    delta: number,
  ) => {
    // Snapshot do item ANTES do setItens para rollback e validação
    const itemSnapshot = itens.find((i) => i.id === itemId);
    if (!itemSnapshot) return;

    const currentBatches = itemSnapshot.selectedBatches || {};
    const currentQty = Number(currentBatches[batchId]) || 0;
    const batch = itemSnapshot.availableBatches?.find((b) => b.id === batchId);
    if (!batch) return;

    const maxQty = Number(batch.quantidade) || 0;
    const newQty = Math.max(0, Math.min(maxQty, currentQty + delta));

    if (isNaN(newQty)) return;

    const newBatches = { ...currentBatches, [batchId]: newQty };

    const totalSent = Object.values(newBatches).reduce(
      (a, b) => (Number(a) || 0) + (Number(b) || 0),
      0,
    );

    const loteString = Object.entries(newBatches)
      .filter(([_, qty]) => qty > 0)
      .map(([id, qty]) => `${id}:${qty}`)
      .join(';');

    // Snapshot do estado anterior para rollback em caso de erro
    const previousSnapshot = {
      selectedBatches: itemSnapshot.selectedBatches,
      quantidade_enviada: itemSnapshot.quantidade_enviada,
      lote: itemSnapshot.lote,
    };

    // Atualização otimista
    setItens((prev) =>
      prev.map((i) =>
        i.id === itemId
          ? {
              ...i,
              selectedBatches: newBatches,
              quantidade_enviada: String(totalSent),
              lote: loteString,
            }
          : i,
      ),
    );

    // Persistência com await + rollback em caso de erro
    (async () => {
      try {
        const { error: updateError } = await supabase
          .from('requisicoes_itens' as any)
          .update({
            quantidade_enviada: String(totalSent),
            lote: loteString,
          })
          .eq('id', itemId);

        if (updateError) throw updateError;

        // Log apenas após sucesso
        if (user && delta !== 0) {
          const nomeUser = myProfileName;
          const nomeProd = itemSnapshot.produto_nome || 'Item';
          const color = colorForUser(user.id);
