1965	  // ── Detecta itens marcados como separados mas SEM etiqueta QR bipada ──
1966	  const detectarNaoBipados = async (): Promise<{ nome: string; qtd: string }[]> => {
1967	    try {
1968	      // 1. Buscar uids bipados nesta requisição
1969	      const { data: eventosData } = await (supabase.from('etiquetas_qr_eventos' as any) as any)
1970	        .select('etiqueta_uid')
1971	        .eq('referencia_tipo', 'requisicao')
1972	        .eq('referencia_id', String(requisicaoId))
1973	        .eq('etapa', 'separacao')
1974	        .in('tipo_evento', ['bipada_separacao', 'reseparada']);
1975	
1976	      const uids: string[] = eventosData
1977	        ? [...new Set((eventosData as any[]).map((e: any) => e.etiqueta_uid as string))]
1978	        : [];
1979	
1980	      // 2. Construir Set de masterIds bipados
1981	      const bipados = new Set<number>();
1982	      if (uids.length > 0) {
1983	        const { data: tagsData } = await (supabase.from('etiquetas_qr' as any) as any)
1984	          .select('produto_master_id')
1985	          .in('uid', uids);
1986	        if (tagsData) {
1987	          (tagsData as any[]).forEach((t: any) => {
1988	            if (t.produto_master_id != null) bipados.add(Number(t.produto_master_id));
1989	          });
1990	        }
1991	      }
1992	
1993	      // 3. Itens marcados (qtd > 0) sem bip confirmado
1994	      return itens
1995	        .filter((item) => parseFloat(item.quantidade_enviada || '0') > 0)
1996	        .filter((item) => item.masterId == null || !bipados.has(item.masterId))
1997	        .map((item) => ({ nome: item.produto_nome, qtd: item.quantidade_enviada || '0' }));
1998	    } catch (e) {
1999	      handleError(e, { domain: 'requisicoes', operation: 'detectarNaoBipados', showToast: false });
2000	      return [];
2001	    }
2002	  };
2003	
2004	  // ── Núcleo da finalização com saída de estoque ──
2005	  // Extrai a lógica crítica original (reserva atômica → RPC → resumo → catch/revert/finally).
2006	  const executarFinalizacaoComSaida = async () => {
2007	    if (!requisicaoId) return;
2008	
2009	    let statusReserved = false;
2010	    try {
2011	      setFinalizando(true);
2012	
2013	      // === GUARD DE RACE CONDITION ===
2014	      // Estratégia: fazer o UPDATE atômico em_progresso -> finalizada ANTES de deduzir estoque.
2015	      // O PostgreSQL serializa UPDATEs concorrentes na mesma linha, então apenas uma sessão
2016	      // conseguirá afetar a linha; as demais receberão 0 rows e abortarão.
2017	      // Se a dedução posterior falhar, revertemos o status no bloco catch.
2018	      const { data: reserveData, error: reserveError } = await supabase
2019	        .from('requisicoes' as any)
2020	        .update({ status: 'finalizada' })
2021	        .eq('id', requisicaoId)
2022	        .eq('status', 'em_progresso')
2023	        .select('id');
2024	
2025	      if (reserveError) throw reserveError;
2026	
2027	      const affected =
2028	        reserveData && Array.isArray(reserveData) ? reserveData.length : 0;
2029	
2030	      if (affected === 0) {
2031	        // Outra sessão já finalizou, ou o status não era 'em_progresso'.
2032	        // Verifica o status atual para dar feedback preciso.
2033	        const { data: currentReq } = await supabase
2034	          .from('requisicoes' as any)
2035	          .select('status')
2036	          .eq('id', requisicaoId)
2037	          .single();
2038	
2039	        const currentStatus = (currentReq as { status?: string } | null)?.status;
2040	        const normalizedCurrent = normalizeRequisicaoStatus(currentStatus);
2041	
2042	        if (normalizedCurrent === 'finalizada') {
2043	          toast({
2044	            title: 'Já finalizada',
2045	            description: 'Esta requisição já foi finalizada por outra sessão.',
2046	            variant: 'destructive',
2047	          });
2048	          navigate('/logistica');
2049	        } else {
2050	          toast({
2051	            title: 'Não foi possível finalizar',
2052	            description: `Status inesperado: ${currentStatus || 'desconhecido'}. Recarregue a página.`,
2053	            variant: 'destructive',
2054	          });
2055	        }
2056	        return;
2057	      }
2058	
2059	      statusReserved = true;
2060	
2061	      // 2. Gerar saídas de estoque para todas as etiquetas QR bipadas nesta requisição.
2062	      //    A RPC é idempotente: re-executar não duplica saídas.
2063	      //    Tipos ainda não regenerados (migration pendente de apply) — usar cast as any
2064	      //    igual ao padrão já consagrado em bipar_etiqueta.
2065	      const { data: saidaRes, error: saidaErr } = await (supabase.rpc as any)(
2066	        'dar_saida_requisicao',
2067	        { p_requisicao_id: Number(requisicaoId) },
2068	      );
2069	
2070	      if (saidaErr || saidaRes?.ok === false) {
2071	        const errMsg = saidaErr?.message || saidaRes?.error || 'erro desconhecido';
2072	        wideError('picking.dar_saida_requisicao_erro', errMsg, {
2073	          domain: 'requisicoes',
2074	          attributes: { requisicaoId },
2075	        });
2076	        // Falha pós-reserva: reverter status para em_progresso para permitir retry.
2077	        throw new Error(
2078	          `Requisição não finalizada: falha ao dar baixa no estoque — ${errMsg}. Tente novamente.`,
2079	        );
2080	      }
2081	
2082	      // 3. Registrar conclusão no Control Tower.
2083	      await logSeparationCompleted(
2084	        Number(requisicaoId),
2085	        myProfileName,
2086	        reqInfo?.loja_solicitante || 'Loja',
2087	        itens.length,
2088	      );
2089	
2090	      // 4. Log user event (broadcast to other users in real-time)
2091	      if (user) {
2092	        const nomeUser = myProfileName;
2093	        channelRef.current?.send({
2094	          type: 'broadcast',
2095	          event: 'user_event',
2096	          payload: { text: `${nomeUser} finalizou a separação` },
2097	        });
2098	      }
2099	
2100	      // 5. Toast de sucesso resumindo as saídas geradas.
2101	      const etiquetasProcessadas = (saidaRes?.etiquetas_processadas as number) ?? 0;
2102	      const jaProcessadas = (saidaRes?.ja_processadas as number) ?? 0;
2103	      const jaProcessadasSufixo =
2104	        jaProcessadas > 0 ? ` (${jaProcessadas} já processadas)` : '';
2105	      toast({
2106	        title: 'Requisição finalizada',
2107	        description: `${etiquetasProcessadas} saída(s) de estoque registrada(s)${jaProcessadasSufixo}.`,
2108	      });
2109	
2110	      // 6. Toast de alerta para itens com saldo insuficiente (zerados na saída).
